// Check the request body and build the Gaffa request. Problems go back to the caller as a 400, so nothing throws here.
const body = $('Receive the request').first().json.body;
const types = ['string', 'integer', 'double', 'decimal', 'boolean', 'datetime', 'array', 'object'];

function checkFields(fields, path) {
  if (!Array.isArray(fields) || fields.length === 0) return `${path} must be a non-empty list`;
  for (const [i, field] of fields.entries()) {
    const at = `${path}[${i}]`;
    if (!field || typeof field.name !== 'string' || !field.name.trim()) return `${at} needs a name`;
    if (typeof field.description !== 'string' || !field.description.trim()) return `${at} needs a description`;
    const type = field.type || 'string';
    if (!types.includes(type)) return `${at} has the unknown type "${type}", use one of ${types.join(', ')}`;
    if (type === 'array' || type === 'object') {
      const nested = checkFields(field.fields, `${at}.fields`);
      if (nested) return nested;
    }
  }
  return '';
}

// Only array and object fields carry nested fields, anything else the caller sends there is dropped.
const toSchema = (fields) => fields.map((field) => {
  const type = field.type || 'string';
  return {
    type,
    name: field.name.trim(),
    description: field.description.trim(),
    ...(type === 'array' || type === 'object' ? { fields: toSchema(field.fields) } : {}),
  };
});

let error = '';
if (!body || typeof body !== 'object') error = 'Send a JSON body with a url and a list of fields';
else if (typeof body.url !== 'string' || !/^https?:\/\/\S+$/i.test(body.url.trim())) error = 'url must be an http or https address';
else if (body.selector != null && typeof body.selector !== 'string') error = 'selector must be a string';
else error = checkFields(body.fields, 'fields');
if (error) return [{ json: { error } }];

const action = {
  type: 'parse_json',
  output_type: 'inline',
  data_schema: { name: 'result', description: 'The requested fields from the page', fields: toSchema(body.fields) },
  ...(typeof body.selector === 'string' && body.selector.trim() ? { selector: body.selector.trim() } : {}),
};
return [{ json: { gaffa_body: {
  url: body.url.trim(),
  max_cache_age: $('Settings').first().json.max_cache_age,
  settings: { time_limit: 60000, actions: [action] },
} } }];
